  // 🚚 Regras de entrega do vendedor (conta/entregas), carrinho por vendedor e encomendas
  "sh.dl.title": { pt: "🚚 Entregas", en: "🚚 Delivery", zh: "🚚 配送", fr: "🚚 Livraison" },
  "sh.dl.box_title": { pt: "🚚 Entrega e levantamento", en: "🚚 Delivery and pickup", zh: "🚚 配送与自取", fr: "🚚 Livraison et retrait" },
  "sh.dl.edit_mine": { pt: "🚚 Mudar as minhas regras de entrega →", en: "🚚 Change my delivery rules →", zh: "🚚 修改我的配送规则 →", fr: "🚚 Modifier mes règles de livraison →" },
  "sh.dl.intro": { pt: "Diga aos clientes como podem receber o que compram: se podem vir buscar ao seu local, se faz entregas e quanto custa a entrega em cada município. O carrinho faz a conta sozinho.", en: "Tell customers how they can get what they buy: whether they can collect it from your place, whether you deliver and how much delivery costs in each municipality. The cart works out the price by itself.", zh: "告诉顾客如何拿到所购商品：是否可以到您的地点自取、您是否配送，以及每个市镇的配送费是多少。购物车会自动计算价格。", fr: "Indiquez aux clients comment ils peuvent recevoir ce qu'ils achètent : s'ils peuvent venir le chercher chez vous, si vous livrez et combien coûte la livraison dans chaque municipalité. Le panier calcule le prix tout seul." },
  "sh.dl.not_configured": { pt: "Ainda não tem regras: os clientes podem escolher levantamento ou entrega e o preço é combinado consigo.", en: "You have no rules yet: customers can choose pickup or delivery and the price is arranged with you.", zh: "您还没有设置规则：顾客可以选择自取或配送，价格与您商定。", fr: "Vous n'avez pas encore de règles : les clients peuvent choisir retrait ou livraison et le prix se convient avec vous." },
  "sh.dl.pickup": { pt: "🏪 Levantamento no local", en: "🏪 Pickup at my place", zh: "🏪 到店自取", fr: "🏪 Retrait chez moi" },
  "sh.dl.pickup_place": { pt: "Onde o cliente vem buscar (opcional)", en: "Where the customer collects it (optional)", zh: "顾客自取地点（可选）", fr: "Où le client vient chercher (facultatif)" },
  "sh.dl.pickup_place_ph": { pt: "Ex.: Mercado do Kapango, banca 12", en: "E.g. Kapango Market, stall 12", zh: "例如：Kapango 市场 12 号摊位", fr: "Ex. : Marché du Kapango, étal 12" },
  "sh.dl.delivery": { pt: "🚚 Faço entregas", en: "🚚 I deliver", zh: "🚚 我提供配送", fr: "🚚 Je livre" },
  "sh.dl.zones": { pt: "Preço por município", en: "Price per municipality", zh: "各市镇价格", fr: "Prix par municipalité" },
  "sh.dl.zones_hint": { pt: "Escolha o município, escreva o preço da entrega e toque em «Adicionar». Pode pôr 0 para entrega grátis.", en: "Choose the municipality, type the delivery price and tap “Add”. You can enter 0 for free delivery.", zh: "选择市镇，输入配送费，然后点“添加”。填 0 表示免费配送。", fr: "Choisissez la municipalité, tapez le prix de livraison et touchez « Ajouter ». Vous pouvez indiquer 0 pour une livraison gratuite." },
