/** Linha de contacto das páginas de informação, na língua escolhida. */
function contactLineIn(lang: Lang, email?: string | null): string {
  if (lang === "pt") return contactLine(email);
  const e = (email ?? "").trim();
  const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
  if (lang === "en") return ok ? `You can contact us by email at ${e}.` : "You can contact us through your account (Account → Help) or by reporting the content concerned.";
  return ok ? `您可以发送邮件至 ${e} 联系我们。` : "您可以通过您的账户（账户 → 帮助）或举报相关内容联系我们。";
}

