/** «Como apagar a minha conta» na língua escolhida (o português vem do core). */
export function deleteAccountPageIn(lang: Lang, email?: string | null): InfoPage {
  const base = deleteAccountPage(email);
  if (lang === "pt") return base;
  const c = contactLineIn(lang, email);
  if (lang === "en") return { ...base, title: "How to delete my account",
    intro: "You can delete your Huambo Online account at any time, on the Website or in the APP.",
    sections: [
      { title: "Steps", paragraphs: [
        "1. Sign in to your account (Website or APP).",
        "2. Open “Your account”.",
        "3. At the end of the page, under “Delete account”, type ELIMINAR and confirm."] },
      { title: "What is deleted", paragraphs: [
        "The account, profile, listings, products, saved items, saved searches, notifications and the data linked to the account.",
        "Reviews you left for other people and messages already sent may be deleted or remain without your name."] },
      { title: "Can't sign in?", paragraphs: [
        "Use “I forgot my password” on the sign-in page to recover access and then delete the account.", c] }
    ] };
  return { ...base, title: "如何删除我的账户",
    intro: "您可以随时在网站或 APP 上删除您的 Huambo Online 账户。",
    sections: [
      { title: "步骤", paragraphs: [
        "1. 登录您的账户（网站或 APP）。",
        "2. 打开“您的账户”。",
        "3. 在页面底部的“删除账户”中输入 ELIMINAR 并确认。"] },
      { title: "会删除哪些内容", paragraphs: [
        "账户、个人资料、信息、商品、收藏、保存的搜索、通知以及与账户相关的数据。",
        "您给他人留下的评价和已发送的消息可能会被删除，或保留但不显示您的名字。"] },
      { title: "无法登录？", paragraphs: [
        "在登录页面使用“忘记密码”恢复访问，然后删除账户。", c] }
    ] };
}
